import { addDays, addMonths } from "@/lib/rules/dates";
import { rule, type Rule } from "@/lib/rules/define";

const CHECKED = "Nov 14, 2026";
const CHECKED_ES = "14 de noviembre de 2026";
export const BATCH5_STATES = ["ME", "MT", "RI", "DE", "SD", "ND", "AK", "VT", "WY"] as const;
export type Batch5State = (typeof BATCH5_STATES)[number];

type Stamp = {
  dueDate: string | null;
  ruleId: string;
  citation: string;
  explanation: string;
  explanationEs: string;
  computation: string;
  unsure: boolean;
};

export function isBatch5(state: string): state is Batch5State {
  return (BATCH5_STATES as readonly string[]).includes(state);
}

function percent(lowestCents: number, proposedCents: number): string {
  const value = Math.round(((proposedCents - lowestCents) * 1_000_000) / lowestCents);
  return (value / 10_000).toFixed(3).replace(/0+$/, "").replace(/\.$/, "");
}

function info(input: {
  id: string; jurisdiction: Batch5State; topic: string; topics: string[];
  titleEn: string; titleEs: string; summaryEn: string; summaryEs: string;
  citation: string; sourceName: string; sourceUrl: string;
}): Rule {
  return rule({
    ...input, findingLabel: "informational", confidence: "high", patterns: [],
    reasonEn: `Loaded for ${input.jurisdiction} only. Checked ${CHECKED}. Not a finding about a particular home.`,
    reasonEs: `Cargado solo para ${input.jurisdiction}. Revisado el ${CHECKED_ES}. No es una conclusión sobre una vivienda.`,
  });
}

const NOT = "This is not permission to withhold rent, repair and deduct, or end the tenancy.";
const NOT_ES = "No es permiso para retener la renta, reparar y descontar, ni terminar el arrendamiento.";

export function batch5Deposit(state: string, triggerDate: string): Stamp | null {
  if (!isBatch5(state)) return null;
  if (state === "ME") {
    const written = addDays(triggerDate, 30);
    const atWill = addDays(triggerDate, 21);
    return {
      dueDate: null, ruleId: "ME-14-6033", citation: "Me. Rev. Stat. Ann. tit. 14, § 6033", unsure: true,
      computation: `A written agreement may set a return time no longer than 30 days (${written} if counted from ${triggerDate}). A tenancy at will uses 21 days (${atWill}) after the later of termination or surrender and acceptance.`,
      explanation: `Section 6032 limits a security deposit to two months' rent. Section 6033 uses the time stated in a written agreement, not to exceed 30 days, or 21 days after the later of termination or surrender and acceptance for a tenancy at will. The agreement type was not entered, so no single date was stored. Normal wear and tear may not be retained. Checked ${CHECKED}.`,
      explanationEs: `El depósito no puede pasar de dos meses. El plazo es el del contrato escrito, hasta 30 días, o 21 días en una tenencia a voluntad. No se guardó una sola fecha. Revisado el ${CHECKED_ES}.`,
    };
  }
  if (state === "MT") {
    const due = addDays(triggerDate, 30);
    return {
      dueDate: due, ruleId: "MT-70-25-202", citation: "Mont. Code Ann. § 70-25-202", unsure: true,
      computation: `${triggerDate} + 30 days = ${due}. A 10-day return applies only when inspection shows no damages, cleaning, or unpaid rent and utilities.`,
      explanation: `Section 70-25-202 requires a written list of rent, damage, and cleaning charges, with the remaining deposit, within 30 days after the earlier of termination or surrender and acceptance. If inspection shows no damages, no cleaning, and no unpaid rent, and the tenant shows utilities are paid, the deposit is returned within 10 days. Using ${triggerDate}, the ordinary date is ${due}. It is unsure because the no-charge path was not confirmed. The opened sections do not state a maximum number of months. Checked ${CHECKED}.`,
      explanationEs: `El plazo ordinario es 30 días. Hay un plazo de 10 días solo si no hay cargos. La fecha es incierta. Revisado el ${CHECKED_ES}.`,
    };
  }
  if (state === "RI") {
    const due = addDays(triggerDate, 20);
    return {
      dueDate: due, ruleId: "RI-34-18-19", citation: "R.I. Gen. Laws § 34-18-19", unsure: true,
      computation: `${triggerDate} + 20 days = ${due} only if that date is the later of termination, delivery of possession, and a forwarding address.`,
      explanation: `Section 34-18-19 limits a security deposit to one month's rent. A separate furniture deposit of up to one month is allowed only when the furniture's replacement value is at least $5,000. The balance and an itemized notice are due within 20 days after the later of termination, delivery of possession, or the tenant's forwarding address. Using ${triggerDate} as that later event, the date is ${due}. It is unsure because the other events were not entered. Ordinary wear and tear is excluded. Checked ${CHECKED}.`,
      explanationEs: `El depósito se limita a un mes. El saldo se entrega a los 20 días del hecho más tardío. La fecha es incierta. Revisado el ${CHECKED_ES}.`,
    };
  }
  if (state === "DE") {
    const due = addDays(triggerDate, 20);
    return {
      dueDate: due, ruleId: "DE-5514", citation: "Del. Code Ann. tit. 25, § 5514", unsure: false,
      computation: `${triggerDate} + 20 days = ${due}.`,
      explanation: `Section 5514 requires the remaining deposit, or an itemized list of damages and the difference, within 20 days after expiration or termination. Using ${triggerDate}, the date is ${due}. For an agreement of one year or more, or a month-to-month tenancy that has lasted a year, the deposit may not exceed one month's rent. Furnished units are excluded from that limit. The term and whether the unit is furnished were not entered, so the cap was not applied. Checked ${CHECKED}.`,
      explanationEs: `La sección 5514 da 20 días. El tope de un mes depende del plazo del contrato y no se aplicó. Revisado el ${CHECKED_ES}.`,
    };
  }
  if (state === "SD") {
    const due = addDays(triggerDate, 21);
    return {
      dueDate: due, ruleId: "SD-43-32-24", citation: "S.D. Codified Laws § 43-32-24", unsure: true,
      computation: `${triggerDate} + 21 days = ${due}. The clock also waits for the tenant's mailing address or delivery instructions.`,
      explanation: `Section 43-32-6.1 limits a residential deposit to one month's rent unless the parties agree to more because special conditions pose a danger to the premises. Section 43-32-24 requires the deposit or a written statement of the specific reason for withholding within 21 days after termination and receipt of the tenant's mailing address or delivery instructions. Using ${triggerDate} as termination, the date is ${due}. It is unsure because receipt of the address was not entered. An itemized accounting is due within 45 days after termination if the tenant requests it. Ordinary wear and tear is excluded. Checked ${CHECKED}.`,
      explanationEs: `El depósito se limita a un mes, salvo acuerdo por condiciones especiales. El plazo de 21 días espera una dirección. La fecha es incierta. Revisado el ${CHECKED_ES}.`,
    };
  }
  if (state === "ND") {
    const due = addDays(triggerDate, 30);
    return {
      dueDate: due, ruleId: "ND-47-16-07.1", citation: "N.D. Cent. Code § 47-16-07.1", unsure: true,
      computation: `${triggerDate} + 30 days = ${due}. The statute also requires delivery of possession.`,
      explanation: `Section 47-16-07.1 generally limits a security deposit to one month's rent. A lessor may accept up to two months from a person with a felony conviction or a prior rental judgment, and a separate pet deposit may be larger. Those exceptions were not applied. The itemization and the amount due must be delivered or mailed within 30 days after termination and delivery of possession. Using ${triggerDate}, the date is ${due}. It is unsure because delivery of possession was not entered separately. Interest was not calculated. Checked ${CHECKED}.`,
      explanationEs: `El depósito general es de un mes. El plazo es 30 días después de la terminación y la entrega. La fecha es incierta. Revisado el ${CHECKED_ES}.`,
    };
  }
  if (state === "AK") {
    const short = addDays(triggerDate, 14);
    const longer = addDays(triggerDate, 30);
    return {
      dueDate: null, ruleId: "AK-34.03.070", citation: "Alaska Stat. § 34.03.070", unsure: true,
      computation: `With a complying termination notice and no damage deduction, 14 days from ${triggerDate} is ${short}. A damage deduction, or a missing termination notice, uses 30 days (${longer}).`,
      explanation: `Section 34.03.070 limits prepaid rent and a security deposit to two months' periodic rent. The limit does not apply when rent exceeds $2,000 a month, and a pet that is not a service animal may require up to one more month. Those exceptions were not applied. The refund is mailed within 14 days after termination and delivery of possession when notice complies with AS 34.03.290 and no damage costs are deducted, and within 30 days when damage costs are deducted or the termination notice does not comply. No single date was stored. Normal wear and tear is excluded. Checked ${CHECKED}.`,
      explanationEs: `El tope general es de dos meses. El reembolso es a los 14 o 30 días según el aviso y los daños. No se guardó una sola fecha. Revisado el ${CHECKED_ES}.`,
    };
  }
  if (state === "VT") {
    const ordinary = addDays(triggerDate, 14);
    return {
      dueDate: null, ruleId: "VT-9-4461", citation: "Vt. Stat. Ann. tit. 9, § 4461", unsure: true,
      computation: `Fourteen days from ${triggerDate} would be ${ordinary}. A seasonal occupancy that is not a primary residence uses 60 days. The clock also depends on when the landlord discovered the tenant left.`,
      explanation: `Section 4461 returns the deposit and an itemized statement within 14 days from the date the landlord discovers the tenant vacated or abandoned, or the date the tenant vacated if the landlord received notice of that date. Seasonal occupancy of a dwelling not intended as a primary residence uses 60 days. No single date was stored. The section states no maximum number of months. A town may adopt a supplemental ordinance, and none was applied. Checked ${CHECKED}.`,
      explanationEs: `El plazo ordinario es 14 días desde que el propietario sabe que el inquilino se fue. Una ocupación de temporada usa 60 días. No se guardó una sola fecha. Revisado el ${CHECKED_ES}.`,
    };
  }
  const ordinary = addDays(triggerDate, 30);
  const afterAddress = addDays(triggerDate, 15);
  return {
    dueDate: null, ruleId: "WY-1-21-1208", citation: "Wyo. Stat. Ann. § 1-21-1208", unsure: true,
    computation: `Thirty days after ${triggerDate} is ${ordinary}. Fifteen days after a new address, if received the same day, is ${afterAddress}. The statute uses the later date, and damage adds another 30 days.`,
    explanation: `Section 1-21-1208 returns the balance and a written itemization within 30 days after termination or 15 days after the renter's new mailing address, whichever is later. Damage to the unit extends that period by 30 days. The renter must give a payment location within 30 days after termination. No single date was stored. The section states no maximum number of months. A nonrefundable portion must be stated in the agreement and in a written notice when the deposit is taken. Checked ${CHECKED}.`,
    explanationEs: `El plazo es el más tardío entre 30 días y 15 días después de la nueva dirección, y los daños suman 30 días. No se guardó una sola fecha. Revisado el ${CHECKED_ES}.`,
  };
}

export function batch5Repair(state: string, requestDate: string): Stamp | null {
  if (!isBatch5(state)) return null;
  const base = { dueDate: null as string | null, unsure: true, computation: `Notice ${requestDate}. No single repair date was stored.` };
  const text: Record<Batch5State, Pick<Stamp, "ruleId" | "citation" | "explanation" | "explanationEs">> = {
    ME: { ruleId: "ME-14-6021", citation: "Me. Rev. Stat. Ann. tit. 14, § 6021", explanation: `Section 6021 is a warranty that the dwelling is fit for human habitation. A court case requires written notice, a condition the tenant did not cause, and rent that was current when notice was given. It states no number of days, so no date was stored from ${requestDate}. The 68-degree heat standard was not applied because the indoor temperature was not entered. ${NOT} Checked ${CHECKED}.`, explanationEs: `La sección 6021 no fija días. No es permiso para retener la renta. Revisado el ${CHECKED_ES}.` },
    MT: { ruleId: "MT-70-24-303", citation: "Mont. Code Ann. § 70-24-303", explanation: `Section 70-24-303 requires a fit and habitable premises and maintenance of supplied systems. It states no number of days, so no date was stored from ${requestDate}. ${NOT} Checked ${CHECKED}.`, explanationEs: `La sección 70-24-303 no fija días. No es permiso para retener la renta. Revisado el ${CHECKED_ES}.` },
    RI: { ruleId: "RI-34-18-22", citation: "R.I. Gen. Laws § 34-18-22", explanation: `Section 34-18-22 requires a fit and habitable premises, supplied systems, and reasonable heat between October 1 and May 1. It states no repair day count, so no date was stored from ${requestDate}. ${NOT} Checked ${CHECKED}.`, explanationEs: `La sección 34-18-22 no fija un plazo de reparación. No es permiso para retener la renta. Revisado el ${CHECKED_ES}.` },
    DE: { ruleId: "DE-5305", citation: "Del. Code Ann. tit. 25, § 5305", explanation: `Section 5305 requires a fit rental unit and repairs necessary to keep it in the condition it ought to have been in at the start. It states no day count. Section 5306's 15-day period is a path to end the agreement, and the essential-service deduction is a separate remedy with its own conditions. Neither was stored as a repair deadline from ${requestDate}. ${NOT} Checked ${CHECKED}.`, explanationEs: `La sección 5305 no fija un plazo. El aviso de 15 días es para terminar el contrato. No es permiso para retener la renta. Revisado el ${CHECKED_ES}.` },
    SD: { ruleId: "SD-43-32-8", citation: "S.D. Codified Laws § 43-32-8", explanation: `Section 43-32-8 requires the lessor to keep residential premises in reasonable repair and fit for human habitation. It states no day count. An agreement that the tenant perform specified repairs in lieu of rent is a separate bargain and was not treated as permission. No date was stored from ${requestDate}. ${NOT} Checked ${CHECKED}.`, explanationEs: `La sección 43-32-8 no fija días. No es permiso para retener la renta. Revisado el ${CHECKED_ES}.` },
    ND: { ruleId: "ND-47-16-13.1", citation: "N.D. Cent. Code § 47-16-13.1", explanation: `Section 47-16-13.1 requires a fit and habitable premises and allows a reasonable time to remedy noncompliance with the maintenance duties. It states no number of days, so no date was stored from ${requestDate}. ${NOT} Checked ${CHECKED}.`, explanationEs: `La sección 47-16-13.1 habla de un tiempo razonable y no fija días. No es permiso para retener la renta. Revisado el ${CHECKED_ES}.` },
    AK: { ruleId: "AK-34.03.100", citation: "Alaska Stat. § 34.03.100", explanation: `Section 34.03.100 requires the landlord to keep the premises fit and habitable and to maintain supplied facilities. It states no repair day count. Section 34.03.180 is a separate essential-services remedy and was not stored as permission. No date was stored from ${requestDate}. ${NOT} Checked ${CHECKED}.`, explanationEs: `La sección 34.03.100 no fija un plazo. La sección de servicios esenciales no se guardó como permiso. Revisado el ${CHECKED_ES}.` },
    VT: { ruleId: "VT-9-4457", citation: "Vt. Stat. Ann. tit. 9, § 4457", explanation: `Section 4457 requires premises that are safe, clean, and fit for human habitation, with heating facilities capable of a reasonable amount of heat and an adequate water supply. It states no day count, so no date was stored from ${requestDate}. ${NOT} Checked ${CHECKED}.`, explanationEs: `La sección 4457 no fija días. No es permiso para retener la renta. Revisado el ${CHECKED_ES}.` },
    WY: { ruleId: "WY-1-21-1203", citation: "Wyo. Stat. Ann. § 1-21-1203", explanation: `Section 1-21-1203 requires the owner, within a reasonable time after written notice, to start correcting a health or safety condition or to dispute the claim. It states no number of days. The three-day statement in section 1-21-1206 comes before a court case and was not stored as a repair deadline from ${requestDate}. ${NOT} Checked ${CHECKED}.`, explanationEs: `La sección 1-21-1203 habla de un tiempo razonable. Los tres días son antes de un juicio. No es permiso para retener la renta. Revisado el ${CHECKED_ES}.` },
  };
  return { ...base, ...text[state] };
}

function windowFlag(activityDate: string, noticeDate: string, daysSince: number, months: number | null, days: number | null): { flagged: boolean; end: string } {
  const end = months !== null ? addMonths(activityDate, months) : addDays(activityDate, days || 0);
  return { flagged: daysSince >= 0 && noticeDate <= end, end };
}

export function batch5Retaliation(state: string, activityDate: string, noticeDate: string, daysSince: number): (Stamp & { flagged: boolean; daysSince: number }) | null {
  if (!isBatch5(state)) return null;
  if (state === "ME" || state === "MT" || state === "RI") {
    const { flagged, end } = windowFlag(activityDate, noticeDate, daysSince, 6, null);
    const citation = state === "ME" ? "Me. Rev. Stat. Ann. tit. 14, § 6001" : state === "MT" ? "Mont. Code Ann. § 70-24-431" : "R.I. Gen. Laws § 34-18-46";
    const ruleId = state === "ME" ? "ME-14-6001" : state === "MT" ? "MT-70-24-431" : "RI-34-18-46";
    return {
      flagged, daysSince, dueDate: null, ruleId, citation, unsure: false,
      computation: `${activityDate} plus six months = ${end}.`,
      explanation: flagged
        ? `The later date is inside six months (${end}). ${citation} creates a rebuttable presumption for a listed retaliatory act in that period. It is not a finding. Exceptions, including nonpayment and a complaint made after notice of a proposed increase, were not decided. Checked ${CHECKED}.`
        : `The later date is outside six months (${end}). Being outside the presumption is not a finding that the act was lawful. Checked ${CHECKED}.`,
      explanationEs: flagged
        ? `La fecha posterior está dentro de seis meses (${end}). Hay una presunción, no una conclusión. Revisado el ${CHECKED_ES}.`
        : `La fecha posterior está fuera de seis meses (${end}). Estar fuera no significa que el acto sea lícito. Revisado el ${CHECKED_ES}.`,
    };
  }
  if (state === "DE") {
    const { flagged, end } = windowFlag(activityDate, noticeDate, daysSince, null, 90);
    return {
      flagged, daysSince, dueDate: null, ruleId: "DE-5516", citation: "Del. Code Ann. tit. 25, § 5516", unsure: false,
      computation: `${activityDate} + 90 days = ${end}.`,
      explanation: flagged
        ? `The later date is inside 90 days (${end}). Section 5516 presumes a listed act is retaliatory when the tenant proves it was instituted within 90 days after a listed complaint. It is not a finding. The listed defenses were not decided. Checked ${CHECKED}.`
        : `The later date is outside 90 days (${end}). Being outside the presumption is not a finding that the act was lawful. Checked ${CHECKED}.`,
      explanationEs: flagged ? `La fecha posterior está dentro de 90 días (${end}). Hay una presunción, no una conclusión. Revisado el ${CHECKED_ES}.` : `La fecha posterior está fuera de 90 días (${end}). Estar fuera no significa que el acto sea lícito. Revisado el ${CHECKED_ES}.`,
    };
  }
  if (state === "SD") {
    const { flagged, end } = windowFlag(activityDate, noticeDate, daysSince, null, 180);
    return {
      flagged, daysSince, dueDate: null, ruleId: "SD-43-32-27", citation: "S.D. Codified Laws § 43-32-27", unsure: false,
      computation: `${activityDate} + 180 days = ${end}.`,
      explanation: flagged
        ? `The later date is inside 180 days (${end}). Section 43-32-27 gives a cause of action for a rent increase above fair-market value, a cut in utility service, or a notice to vacate that is not based on a lease breach, after a listed special event. A notice to vacate more than 180 days later is a defense. It is not a finding, and failure to renew a written lease at expiration is not retaliation. Checked ${CHECKED}.`
        : `The later date is outside 180 days (${end}). A notice to vacate after that period is a defense under section 43-32-27. That is not a finding that every later act was lawful. Checked ${CHECKED}.`,
      explanationEs: flagged ? `La fecha posterior está dentro de 180 días (${end}). No es una conclusión. Revisado el ${CHECKED_ES}.` : `La fecha posterior está fuera de 180 días (${end}). Ese plazo es una defensa al aviso de desalojo. Revisado el ${CHECKED_ES}.`,
    };
  }
  const notes: Record<"ND" | "AK" | "VT" | "WY", Stamp> = {
    ND: { dueDate: null, ruleId: "ND-47-16", citation: "N.D. Cent. Code ch. 47-16", unsure: true, computation: "No general day count in chapter 47-16.", explanation: `Chapter 47-16, as opened on ${CHECKED}, does not state a general retaliation period, so no date was flagged. A sentence in the domestic-violence termination section says a person may not retaliate solely because a tenant used that termination right. That sentence was not applied to an ordinary complaint. It is not a finding. Checked ${CHECKED}.`, explanationEs: `El capítulo 47-16 no fija un plazo general de represalia. No se marcó una fecha. Revisado el ${CHECKED_ES}.` },
    AK: { dueDate: null, ruleId: "AK-34.03.310", citation: "Alaska Stat. § 34.03.310", unsure: true, computation: "No day count. AS 34.03.310 does not state a number of days.", explanation: `Section 34.03.310 says a landlord may not retaliate by increasing rent, decreasing services, or bringing a possession action after a listed tenant act. It states no number of days, so no date was flagged. Listed exceptions, including nonpayment, were not decided. It is not a finding. Checked ${CHECKED}.`, explanationEs: `La sección 34.03.310 no fija días, así que no se marcó una fecha. No es una conclusión. Revisado el ${CHECKED_ES}.` },
    VT: { dueDate: null, ruleId: "VT-9-4465", citation: "Vt. Stat. Ann. tit. 9, § 4465", unsure: true, computation: "No general day count. A 90-day presumption applies only after a government noncompliance notice.", explanation: `Section 4465 prohibits retaliation by changing rental terms or bringing an action after a listed complaint or tenant organizing. It states no general number of days, so no date was flagged. A rebuttable presumption applies when a termination notice, other than for nonpayment, is served within 90 days after a municipal or state notice that the premises are out of compliance. That government notice was not entered. It is not a finding. Checked ${CHECKED}.`, explanationEs: `La sección 4465 no fija un plazo general. La presunción de 90 días exige un aviso del gobierno y no se aplicó. Revisado el ${CHECKED_ES}.` },
    WY: { dueDate: null, ruleId: "WY-1-21-1201", citation: "Wyo. Stat. Ann. §§ 1-21-1201 to 1-21-1211", unsure: true, computation: "No retaliation section in the residential article opened.", explanation: `Article 12 of title 1, chapter 21, as opened on ${CHECKED}, does not state a retaliation period, so no date was flagged. It is not a finding. Checked ${CHECKED}.`, explanationEs: `El artículo residencial abierto no fija un plazo de represalia. No se marcó una fecha. Revisado el ${CHECKED_ES}.` },
  };
  if (state !== "ND" && state !== "AK" && state !== "VT" && state !== "WY") return null;
  return { ...notes[state], flagged: false, daysSince };
}

export function batch5Rent(state: string, lowestCents: number, proposedCents: number) {
  if (!isBatch5(state)) return null;
  const amount = percent(lowestCents, proposedCents);
  const base = { abovePublishedMax: false as const };
  const entered = `The increase from the amounts entered is about ${amount}%.`;
  if (state === "ME") return { ...base, headlineEn: "Maine rent increase", headlineEs: "Aumento de renta en Maine", ruleId: "ME-14-6015", detailEn: `${entered} Section 6015 requires at least 45 days' written notice, or 75 days when the increase is 10 percent or more. The amounts entered are ${Number(amount) >= 10 ? "at least 10 percent, so the longer notice is the one the section describes" : "under 10 percent, so the 45-day notice is the one the section describes"}. Whether notice was actually given was not graded. Section 6016 says rent may not be increased while the unit violates the warranty of habitability. That condition was not decided. There is no percentage cap. Portland's local rent ordinance was not applied. Checked ${CHECKED}.`, detailEs: `El aumento es de alrededor del ${amount}%. El aviso es de 45 días, o 75 si llega al 10 por ciento. No se calificó si el aviso se dio. Revisado el ${CHECKED_ES}.` };
  if (state === "MT") return { ...base, headlineEn: "Montana rent increase", headlineEs: "Aumento de renta en Montana", ruleId: "MT-70-24-201", detailEn: `${entered} Section 70-24-201 lets the agreement set the rent and states no percentage cap and no rent-increase notice. No notice period was graded. A retaliatory increase is a separate limit under section 70-24-431. Checked ${CHECKED}.`, detailEs: `El aumento es de alrededor del ${amount}%. La sección 70-24-201 no fija un tope ni un aviso de aumento. Revisado el ${CHECKED_ES}.` };
  if (state === "RI") return { ...base, headlineEn: "Rhode Island rent increase", headlineEs: "Aumento de renta en Rhode Island", ruleId: "RI-34-18-16.1", detailEn: `${entered} Section 34-18-16.1 requires at least 60 days' written notice before a residential rent increase, and at least 120 days for a month-to-month tenant over 62. Age and tenancy type were not entered, so no notice period was graded. The section states no percentage cap. Checked ${CHECKED}.`, detailEs: `El aumento es de alrededor del ${amount}%. El aviso es de 60 días, o 120 para un inquilino de mes a mes mayor de 62. No se calificó. Revisado el ${CHECKED_ES}.` };
  if (state === "DE") return { ...base, headlineEn: "Delaware rent increase", headlineEs: "Aumento de renta en Delaware", ruleId: "DE-5107", detailEn: `${entered} Section 5107 requires at least 60 days' written notice before a rental agreement is renewed with modified provisions, including the amount of rent. Whether this increase is a renewal was not entered, so the notice was not graded. The section states no percentage cap. Manufactured-home community rent rules in chapter 70 were not applied. Checked ${CHECKED}.`, detailEs: `El aumento es de alrededor del ${amount}%. La sección 5107 exige 60 días para renovar con una renta distinta. No se calificó. Revisado el ${CHECKED_ES}.` };
  if (state === "SD") return { ...base, headlineEn: "South Dakota rent increase", headlineEs: "Aumento de renta en Dakota del Sur", ruleId: "SD-43-32-13", detailEn: `${entered} Section 43-32-13 lets a landlord modify a month-to-month lease, including rent, by written notice at least 30 days before the end of the month. The tenant may end the lease effective the first day of the next month by notice within 15 days after receiving that notice. Whether the tenancy is month to month was not entered, so no notice period was graded. The section states no percentage cap. A retaliatory increase above fair-market value is a separate limit under section 43-32-27. Checked ${CHECKED}.`, detailEs: `El aumento es de alrededor del ${amount}%. El aviso de 30 días es para un contrato de mes a mes y no se calificó. Revisado el ${CHECKED_ES}.` };
  if (state === "ND") return { ...base, headlineEn: "North Dakota rent increase", headlineEs: "Aumento de renta en Dakota del Norte", ruleId: "ND-47-16-07", detailEn: `${entered} Section 47-16-07 lets a landlord change a month-to-month lease, including rent, by written notice at least 30 days before the end of the month. Whether the tenancy is month to month was not entered, so the notice was not graded. The section states no percentage cap. Section 47-16-02.1 prohibits a political subdivision from controlling rent for private residential property. Checked ${CHECKED}.`, detailEs: `El aumento es de alrededor del ${amount}%. El aviso de 30 días es para un contrato de mes a mes y no se calificó. Revisado el ${CHECKED_ES}.` };
  if (state === "AK") return { ...base, headlineEn: "Alaska rent increase", headlineEs: "Aumento de renta en Alaska", ruleId: "AK-34.03.020", detailEn: `${entered} Section 34.03.020 lets the agreement set the rent and states no percentage cap. Section 34.03.290 requires at least 30 days' written notice to end a month-to-month tenancy before the rental due date. That period ends the tenancy and was not graded as a rent increase. A retaliatory increase is a separate limit under section 34.03.310. Checked ${CHECKED}.`, detailEs: `El aumento es de alrededor del ${amount}%. No hay un tope estatal. La sección 34.03.290 no se usó para calificar un aumento. Revisado el ${CHECKED_ES}.` };
  if (state === "VT") return { ...base, headlineEn: "Vermont rent increase", headlineEs: "Aumento de renta en Vermont", ruleId: "VT-9-4455", detailEn: `${entered} Section 4455 says an increase takes effect on the first day of the rental period following no less than 60 days' actual notice. The rental period and the notice date were not entered, so the notice was not graded. The section states no percentage cap. Burlington's local rent ordinance was not applied. Checked ${CHECKED}.`, detailEs: `El aumento es de alrededor del ${amount}%. La sección 4455 exige 60 días de aviso real. No se calificó. Revisado el ${CHECKED_ES}.` };
  return { ...base, headlineEn: "Wyoming rent increase", headlineEs: "Aumento de renta en Wyoming", ruleId: "WY-1-21-1202", detailEn: `${entered} Article 12 of title 1, chapter 21, as opened on ${CHECKED}, does not state a percentage cap or a rent-increase notice. No notice period was graded. Checked ${CHECKED}.`, detailEs: `El aumento es de alrededor del ${amount}%. El artículo residencial no fija un tope ni un aviso de aumento. Revisado el ${CHECKED_ES}.` };
}

export function batch5RepairLetter(state: string, locale: "en" | "es"): string | null {
  if (!isBatch5(state)) return null;
  const en: Record<Batch5State, string> = {
    ME: "I am asking you to address this repair. Maine's warranty of habitability does not set a number of days. This letter is not a court complaint and it is not a notice that I am withholding rent. I confirm this message before it is sent.",
    MT: "I am asking you to address this repair. Montana Code Annotated § 70-24-303 does not set a number of days. This letter is not a notice that I am withholding rent or ending the tenancy. I confirm this message before it is sent.",
    RI: "I am asking you to address this repair. Rhode Island General Laws § 34-18-22 does not set a repair deadline. This letter is not a notice that I am withholding rent or ending the tenancy. I confirm this message before it is sent.",
    DE: "I am asking you to address this repair. This letter is not a 15-day termination notice and it is not a notice that I am withholding rent. I confirm this message before it is sent.",
    SD: "I am asking you to address this repair. South Dakota Codified Laws § 43-32-8 does not set a number of days. This letter is not an agreement to repair in place of rent and it is not a notice that I am withholding rent. I confirm this message before it is sent.",
    ND: "I am asking you to address this repair. North Dakota Century Code § 47-16-13.1 does not set a number of days. This letter is not a notice that I am withholding rent or ending the tenancy. I confirm this message before it is sent.",
    AK: "I am asking you to address this repair. Alaska Statutes § 34.03.100 does not set a repair deadline. This letter is not a notice that I am deducting the cost of essential services or withholding rent. I confirm this message before it is sent.",
    VT: "I am asking you to address this repair. Vermont Statutes Annotated title 9, § 4457 does not set a number of days. This letter is not a notice that I am withholding rent or ending the tenancy. I confirm this message before it is sent.",
    WY: "I am asking you to address this repair. This letter is not the notice that starts a court case and it is not a notice that I am withholding rent. I confirm this message before it is sent.",
  };
  const es: Record<Batch5State, string> = {
    ME: "Le pido que atienda esta reparación. Esta carta no es una demanda ni un aviso de que retengo la renta. Confirmo este mensaje antes de enviarlo.",
    MT: "Le pido que atienda esta reparación. El código de Montana no fija un número de días. Esta carta no avisa que retengo la renta. Confirmo este mensaje antes de enviarlo.",
    RI: "Le pido que atienda esta reparación. La ley de Rhode Island no fija un plazo de reparación. Esta carta no avisa que retengo la renta. Confirmo este mensaje antes de enviarlo.",
    DE: "Le pido que atienda esta reparación. Esta carta no es un aviso de 15 días para terminar el contrato ni un aviso de que retengo la renta. Confirmo este mensaje antes de enviarlo.",
    SD: "Le pido que atienda esta reparación. Esta carta no es un acuerdo para reparar en lugar de pagar renta. Confirmo este mensaje antes de enviarlo.",
    ND: "Le pido que atienda esta reparación. El código de Dakota del Norte no fija un número de días. Esta carta no avisa que retengo la renta. Confirmo este mensaje antes de enviarlo.",
    AK: "Le pido que atienda esta reparación. Esta carta no avisa que descontaré servicios esenciales ni que retengo la renta. Confirmo este mensaje antes de enviarlo.",
    VT: "Le pido que atienda esta reparación. El estatuto de Vermont no fija un número de días. Esta carta no avisa que retengo la renta. Confirmo este mensaje antes de enviarlo.",
    WY: "Le pido que atienda esta reparación. Esta carta no es el aviso que inicia un juicio ni un aviso de que retengo la renta. Confirmo este mensaje antes de enviarlo.",
  };
  return locale === "es" ? es[state] : en[state];
}

